theorem successive_sum_coordinate_bound {k : ℕ} {z : Fin k → C00 𝕜}
    (hz : Successive z) {c : ℝ} (hc : 0 ≤ c) (hb : ∀ i n, ‖z i n‖ ≤ c) (n : ℕ) :
    ‖(∑ i, z i) n‖ ≤ c

