    {weight : ℝ} (hw : 0 < weight) {a : C00 𝕜} (ha : IsForm D k weight a)
    (n : ℕ) : ‖a n‖ ≤ weight⁻¹

theorem IsForm.mass_bound {D : ConstructionData 𝕜} {k : ℕ}
    {weight : ℝ} (hw : 0 < weight) {a : C00 𝕜} (ha : IsForm D k weight a)
    (x : C00 𝕜) : ‖pairing a x‖ ≤ weight⁻¹ * mass x
